// Pre-flight scan v2: n8n 3.0 removals + OpenAI model shutdowns. Reads workflow JSON only. Changes nothing.
const cfg = $('Settings').first().json;
const includeArchived = cfg.includeArchived === true;
const now = new Date();
const REMOVED = {
  'n8n-nodes-base.function': ['Function node (removed in 3.0)', 'Code node, Run Once for All Items'],
  'n8n-nodes-base.functionItem': ['Function Item node (removed in 3.0)', 'Code node, Run Once for Each Item'],
  'n8n-nodes-base.itemLists': ['Item Lists node (removed in 3.0)', 'Split Out / Aggregate / Sort / Limit / Remove Duplicates / Summarize'],
  'n8n-nodes-base.cron': ['Cron node (removed in 3.0)', 'Schedule Trigger'],
  'n8n-nodes-base.interval': ['Interval node (removed in 3.0)', 'Schedule Trigger'],
  'n8n-nodes-base.htmlExtract': ['HTML Extract node (removed in 3.0)', 'HTML node, Extract HTML Content'],
  'n8n-nodes-base.iCal': ['iCalendar node (removed in 3.0)', 'Convert to File, Convert to ICS'],
  'n8n-nodes-base.moveBinaryData': ['Convert to/from binary data node (removed in 3.0)', 'Convert to File / Extract from File'],
  'n8n-nodes-base.readBinaryFile': ['Read Binary File node (removed in 3.0)', 'Read/Write Files from Disk'],
  'n8n-nodes-base.readBinaryFiles': ['Read Binary Files node (removed in 3.0)', 'Read/Write Files from Disk'],
  'n8n-nodes-base.writeBinaryFile': ['Write Binary File node (removed in 3.0)', 'Read/Write Files from Disk'],
  'n8n-nodes-base.readPDF': ['Read PDF node (removed in 3.0)', 'Extract from File, Extract From PDF'],
  'n8n-nodes-base.workflowTrigger': ['Workflow Trigger node (removed in 3.0)', 'n8n Trigger node'],
  'n8n-nodes-base.orbit': ['Orbit node (removed in 3.0)', 'none: the Orbit service shut down'],
  'n8n-nodes-base.openAi': ['Legacy OpenAI node (removed in 3.0)', 'current OpenAI node'],
  'n8n-nodes-base.serpApi': ['SerpApi node (removed in 3.0)', 'HTTP Request node as an agent tool, or a verified community node'],
  '@n8n/n8n-nodes-langchain.openAiAssistant': ['OpenAI Assistant node (removed in 3.0; OpenAI ended the Assistants API 2026-08-26)', 'current OpenAI node, Assistant resource'],
  '@n8n/n8n-nodes-langchain.lmOpenAi': ['OpenAI Model node (removed in 3.0)', 'OpenAI Chat Model node'],
  '@n8n/n8n-nodes-langchain.code': ['LangChain Code node (removed in 3.0)', 'no direct replacement'],
  '@n8n/n8n-nodes-langchain.manualChatTrigger': ['Manual Chat Trigger (removed in 3.0)', 'Chat Trigger'],
  '@n8n/n8n-nodes-langchain.memoryChatRetriever': ['Chat Messages Retriever (removed in 3.0)', 'Chat Memory Manager'],
  '@n8n/n8n-nodes-langchain.memoryMotorhead': ['Motorhead memory (removed in 3.0)', 'another supported memory node'],
  '@n8n/n8n-nodes-langchain.memoryZep': ['Zep memory (removed in 3.0)', 'another supported memory node'],
  '@n8n/n8n-nodes-langchain.documentBinaryInputLoader': ['Binary Input Loader (removed in 3.0)', 'Default Data Loader'],
  '@n8n/n8n-nodes-langchain.documentJsonInputLoader': ['JSON Input Loader (removed in 3.0)', 'Default Data Loader'],
  '@n8n/n8n-nodes-langchain.documentGithubLoader': ['GitHub Document Loader (removed in 3.0)', 'GitHub node + Default Data Loader'],
  '@n8n/n8n-nodes-langchain.vectorStoreInMemoryInsert': ['In Memory Vector Store Insert (removed in 3.0)', 'Simple Vector Store node'],
  '@n8n/n8n-nodes-langchain.vectorStoreInMemoryLoad': ['In Memory Vector Store Load (removed in 3.0)', 'Simple Vector Store node'],
  '@n8n/n8n-nodes-langchain.vectorStorePineconeInsert': ['Pinecone: Insert (removed in 3.0)', 'Pinecone Vector Store node'],
  '@n8n/n8n-nodes-langchain.vectorStorePineconeLoad': ['Pinecone: Load (removed in 3.0)', 'Pinecone Vector Store node'],
  '@n8n/n8n-nodes-langchain.vectorStoreSupabaseInsert': ['Supabase: Insert (removed in 3.0)', 'Supabase Vector Store node'],
  '@n8n/n8n-nodes-langchain.vectorStoreSupabaseLoad': ['Supabase: Load (removed in 3.0)', 'Supabase Vector Store node'],
  '@n8n/n8n-nodes-langchain.vectorStoreZep': ['Zep Vector Store (removed in 3.0)', 'another supported vector store'],
  '@n8n/n8n-nodes-langchain.vectorStoreZepInsert': ['Zep Vector Store: Insert (removed in 3.0)', 'another supported vector store'],
  '@n8n/n8n-nodes-langchain.vectorStoreZepLoad': ['Zep Vector Store: Load (removed in 3.0)', 'another supported vector store'],
};
// OpenAI model ids with shutdown dates (source: OpenAI deprecations page, read 2026-10-10). Exact-token match only.
const D1 = '2026-10-23', D2 = '2026-12-01', D3 = '2026-12-11', D4 = '2027-01-06', D5 = '2027-02-26', D6 = '2027-04-01';
const MODEL_DATES = {};
['gpt-3.5-turbo','gpt-3.5-turbo-0125','gpt-4','gpt-4-0613','gpt-4-1106-preview','gpt-4-turbo','gpt-4-turbo-2024-04-09','gpt-4.1-nano','gpt-4.1-nano-2025-04-14','gpt-4o-2024-05-13','gpt-image-1','o1','o1-2024-12-17','o1-pro','o1-pro-2025-03-19','o3-mini','o3-mini-2025-01-31','o4-mini','o4-mini-2025-04-16'].forEach(m => MODEL_DATES[m] = D1);
['gpt-image-1-mini','gpt-image-1.5','chatgpt-image-latest'].forEach(m => MODEL_DATES[m] = D2);
['gpt-5-2025-08-07','gpt-5-mini-2025-08-07','gpt-5-nano-2025-08-07','gpt-5-pro-2025-10-06','o3-2025-04-16','o3-pro-2025-06-10'].forEach(m => MODEL_DATES[m] = D3);
['tts-1','tts-1-hd','gpt-4o-mini-tts-2025-03-20','gpt-4o-mini-tts-2025-12-15'].forEach(m => MODEL_DATES[m] = D4);
['whisper-1','gpt-4o-transcribe','gpt-4o-mini-transcribe','gpt-4o-transcribe-diarize'].forEach(m => MODEL_DATES[m] = D5);
['gpt-5.3-codex','gpt-5.4-nano','gpt-5.1'].forEach(m => MODEL_DATES[m] = D6);

REMOVED['@n8n/n8n-nodes-langchain.toolHttpRequest'] = ['Legacy HTTP Request Tool node (removed in 3.0)', 'HTTP Request node connected as an agent tool (n8n-nodes-base.httpRequestTool)'];
// Fix steps for the most common removals. Others fall back to the replacement name.
const FIX = {
  'n8n-nodes-base.function': 'Add a Code node (Run Once for All Items), paste the code, change `items` to `$input.all()` and return an array of {json} objects.',
  'n8n-nodes-base.functionItem': 'Add a Code node (Run Once for Each Item), paste the code, change `item` to `$json`.',
  'n8n-nodes-base.cron': 'Add a Schedule Trigger with the same times (Custom cron is available), then delete the Cron node.',
  'n8n-nodes-base.interval': 'Add a Schedule Trigger with the same interval, then delete the Interval node.',
  'n8n-nodes-base.itemLists': 'Pick the matching node for the operation used: Split Out, Aggregate, Sort, Limit, Remove Duplicates or Summarize.',
  '@n8n/n8n-nodes-langchain.toolHttpRequest': 'Add an HTTP Request node to the agent tool slot, copy URL, method and auth, and use $fromAI() for values the agent fills.',
  '@n8n/n8n-nodes-langchain.openAiAssistant': 'Move the prompt and tools to an AI Agent node with the OpenAI Chat Model, or the OpenAI node (Responses).',
};
// Candidate replacement per model. Confirm on OpenAI's deprecations page before switching; test output quality.
const MODEL_FIX = [
  [/^(gpt-3\.5|gpt-4$|gpt-4-0613|gpt-4-1106|gpt-4-turbo)/, 'gpt-4.1'],
  [/^gpt-4\.1-nano/, 'gpt-4.1-mini'],
  [/^gpt-4o-2024-05-13/, 'gpt-4o'],
  [/^(o1|o3-mini|o4-mini)/, 'o3 (alias)'],
  [/^(gpt-5|gpt-5-mini|gpt-5-nano|gpt-5-pro|o3|o3-pro)-20/, 'the same model alias without the date, or a newer model'],
  [/image/, 'the current GPT Image model'],
  [/^(tts|gpt-4o-mini-tts)/, 'the current OpenAI TTS model'],
  [/(whisper|transcribe)/, 'the current OpenAI transcribe model'],
  [/^gpt-5\.(1|3|4)/, 'a newer GPT-5.x model'],
];
const modelFix = m => (MODEL_FIX.find(([re]) => re.test(m)) || [null, 'a current model'])[1];
const daysTo = d => Math.ceil((new Date(d + 'T00:00:00Z') - now) / 86400000);
// Severity: critical 4, high 3, medium 2, low 1. Inactive workflows drop one level, archived drop to low.
const LEVELS = ['low', 'medium', 'high', 'critical'];
function grade(base, wf) {
  let i = LEVELS.indexOf(base);
  if (wf.isArchived) i = 0; else if (!wf.active) i = Math.max(0, i - 1);
  return LEVELS[i];
}

const all = $input.all().map(i => i.json).filter(w => w && Array.isArray(w.nodes));
// This workflow itself is always on the instance, so zero workflows means the API read failed.
if (!all.length) throw new Error('No workflows came back from the n8n API. Check the API credential and that the key can list workflows.');
const skipped = all.filter(w => w.isArchived && !includeArchived).map(w => w.name);
const flows = all.filter(w => includeArchived || !w.isArchived);
const findings = [];
for (const w of flows) {
  const status = w.isArchived ? 'archived' : (w.active ? 'active' : 'inactive');
  for (const n of w.nodes) {
    const base = { workflow: w.name, workflowId: w.id, status, node: n.name, nodeId: n.id || n.name, nodeType: n.type };
    const add = (code, kind, sev, issue, replacement, fix, deadline) =>
      findings.push({ ...base, key: `${w.id}|${n.id || n.name}|${code}`, kind, severity: grade(sev, w), issue, replacement, fix, deadline });
    const P = JSON.stringify(n.parameters || {});
    if (REMOVED[n.type]) add('removed:' + n.type, 'n8n 3.0', 'high', REMOVED[n.type][0], REMOVED[n.type][1], FIX[n.type] || 'Replace with: ' + REMOVED[n.type][1] + '.', 'n8n 3.0 upgrade');
    if (n.type === '@n8n/n8n-nodes-langchain.agent' && Number(n.typeVersion) < 1.1)
      add('agent-v1', 'n8n 3.0', 'high', 'AI Agent node version 1 (removed in 3.0)', 'AI Agent, latest version (Tools Agent)', 'Open the node and update it to the latest version, then re-check the prompt and tool connections.', 'n8n 3.0 upgrade');
    if (n.type === 'n8n-nodes-base.executeWorkflow' && n.parameters && ['url', 'localFile'].includes(n.parameters.source))
      add('subwf-source', 'n8n 3.0', 'high', `Execute Sub-workflow uses source "${n.parameters.source}" (removed in 3.0)`, 'Database source (pick the workflow from the list)', 'Import the sub-workflow into this instance and select it with "From list".', 'n8n 3.0 upgrade');
    if (P.includes('$getPairedItem'))
      add('getPairedItem', 'n8n 3.0', 'medium', '$getPairedItem helper (removed in 3.0)', "$('Node').item / itemMatching()", "Change $getPairedItem(...) to $('Node name').item or $('Node name').itemMatching(index).", 'n8n 3.0 upgrade');
    if (/\{\{[^}]*\b(gpt|o[134])[^}]*\}\}/i.test(P) && /model/i.test(P))
      add('model-expr', 'review', 'low', 'Model name is set by an expression; the scan cannot read its run-time value', 'n/a', 'Check the values that expression can produce against the shutdown list.', 'n/a');
    const tokens = new Set(P.toLowerCase().match(/(?:ft:)?(?:gpt|chatgpt|o[134]|tts|whisper)[a-z0-9.\-]*/g) || []);
    for (const t of tokens) {
      const bare = t.replace(/^ft:/, '').split(':')[0];
      const d = MODEL_DATES[bare];
      if (!d) continue;
      const left = daysTo(d);
      const sev = left <= 30 ? 'critical' : left <= 90 ? 'high' : 'medium';
      add('model:' + bare, 'OpenAI model', sev, `OpenAI model "${t}" shuts down on ${d} (${left < 0 ? 'already past' : left + ' days left'})`, modelFix(bare), `Change the model to ${modelFix(bare)} and run a test execution to compare outputs.`, d);
    }
  }
}
const W = { critical: 40, high: 15, medium: 5, low: 1 };
return [{ json: { scannedAt: now.toISOString(), workflowsScanned: flows.length, archivedSkipped: skipped, findings, riskScore: findings.reduce((s, f) => s + W[f.severity], 0) } }];

// Compare with the previous run. Static data is saved only on production (scheduled) runs, so a manual run shows everything.
const cfg = $('Settings').first().json;
const cur = $input.first().json;
const store = $getWorkflowStaticData('global');
const prev = new Set(store.lastKeys || []);
const firstRun = !store.lastRunAt;
const keys = cur.findings.map(f => f.key);
const isNew = f => firstRun || !prev.has(f.key);
const findings = cur.findings.map(f => ({ ...f, isNew: isNew(f) }));
const resolved = [...prev].filter(k => !keys.includes(k));
const previousRunAt = store.lastRunAt || null;
store.lastKeys = keys;
store.lastRunAt = cur.scannedAt;
const onlyNew = cfg.onlyNewIssues === true && !firstRun;
const report = onlyNew ? findings.filter(f => f.isNew) : findings;
return [{ json: { ...cur, firstRun, previousRunAt, findings, report, onlyNew, newCount: findings.filter(f => f.isNew).length, resolvedCount: resolved.length, resolved } }];

// Build one HTML report, grouped by workflow, worst first.
const cfg = $('Settings').first().json;
const r = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const ORDER = { critical: 0, high: 1, medium: 2, low: 3 };
const COLOR = { critical: '#b00020', high: '#e65100', medium: '#b8860b', low: '#607d8b' };
const minRank = ORDER[cfg.minSeverity] ?? 3;
const rows = r.report.filter(f => ORDER[f.severity] <= minRank).sort((a, b) => ORDER[a.severity] - ORDER[b.severity]);
const count = s => r.findings.filter(f => f.severity === s).length;
const groups = {};
for (const f of rows) (groups[f.workflowId] ||= { name: f.workflow, status: f.status, items: [] }).items.push(f);
const base = String(cfg.instanceUrl || '').replace(/\/+$/, '');
let html = `<h2>n8n pre-flight scan</h2><p>${r.workflowsScanned} workflows scanned. Risk score ${r.riskScore}. `
  + ['critical', 'high', 'medium', 'low'].map(s => `<b style="color:${COLOR[s]}">${count(s)} ${s}</b>`).join(', ')
  + `. New since last run: ${r.firstRun ? 'first run' : r.newCount}. Resolved: ${r.resolvedCount}.</p>`;
if (r.onlyNew) html += '<p>Showing new issues only (onlyNewIssues = true).</p>';
for (const [id, g] of Object.entries(groups)) {
  const link = base ? `<a href="${esc(base)}/workflow/${esc(id)}">${esc(g.name)}</a>` : esc(g.name);
  html += `<h3>${link} <small>(${esc(g.status)}, ${g.items.length})</small></h3><table border="1" cellpadding="4" cellspacing="0" style="border-collapse:collapse;font-size:13px">`
    + '<tr><th>Severity</th><th>Node</th><th>Issue</th><th>Replace with</th><th>How to fix</th></tr>'
    + g.items.map(f => `<tr><td style="color:${COLOR[f.severity]}"><b>${f.severity}</b>${f.isNew && !r.firstRun ? ' NEW' : ''}</td><td>${esc(f.node)}</td><td>${esc(f.issue)}</td><td>${esc(f.replacement)}</td><td>${esc(f.fix)}</td></tr>`).join('')
    + '</table>';
}
if (r.archivedSkipped.length) html += `<p>Archived workflows skipped (${r.archivedSkipped.length}): ${r.archivedSkipped.map(esc).join(', ')}.</p>`;
html += '<p><small>Fixed lists, not a guarantee. Also run Settings &gt; Migration Report on your instance. Model dates: OpenAI deprecations page, read 2026-10-10.</small></p>';
const send = rows.length > 0 || cfg.sendWhenClean === true;
const subject = rows.length ? `[n8n] pre-flight scan: ${rows.length} to review (${count('critical')} critical in total)` : '[n8n] pre-flight scan: nothing to report';
const text = `${subject}. Risk score ${r.riskScore}. New: ${r.firstRun ? 'first run' : r.newCount}. Resolved: ${r.resolvedCount}.`;
const sheetRows = rows.map(f => ({ scannedAt: r.scannedAt, workflow: f.workflow, workflowId: f.workflowId, status: f.status, node: f.node, severity: f.severity, issue: f.issue, replacement: f.replacement, deadline: f.deadline, isNew: f.isNew }));
return [{ json: { send, subject, html, text, sheetRows, shown: rows.length } }];
